select id, call_log_id, call_no, contract_id, contract_product_id, customer_id, supplier_id,
       supplier_account_id,
       product_id, product_code, total_tokens, total_fees, actual_fees, base_sell_price, sell_discount, sell_amount,
       base_cost_price, cost_discount, cost_amount, gross_profit, match_status, match_msg,
       call_time, bill_id, usage_type, ref_usage_id, create_time, update_time
from crm_contract_usage
where bill_id is null and usage_type = 0
  and call_time >= #{startTime} and call_time <= #{endTime}
   and supplier_id = #{supplierId}
   and customer_id = #{customerId}

      and match_status in

          #{matchStatus}



      and supplier_id in

          #{scopeSupplierId}


order by call_time, id
limit 20000

select cp.id as contract_product_id, c.id as contract_id, c.contact_no as contact_no, cp.supplier_id as supplier_id, cp.supplier_account_id as supplier_account_id, cp.sell_discount as sell_discount, cp.cost_discount as cost_discount from crm_contract c inner join crm_contract_product cp on cp.contract_id = c.id and cp.deleted = 0 where c.deleted = 0 and c.status = 2 and c.consumer_id = #{customerId} and cp.supplier_id = #{supplierId} and cp.product_id = #{productId}
and (cp.supplier_account_id = #{supplierAccountId} or cp.supplier_account_id is null)
order by c.sign_time desc, c.id desc, cp.id

mapper.update:
update crm_contract_usage
set bill_id = #{billId}, update_time = sysdate()
where bill_id is null
  and match_status = 1
  and contract_id = #{contractId}
  and supplier_id = #{supplierId}
  and call_time >= #{startTime} and call_time <= #{endTime}

mapper.select:
select a.customer_id, cu.name as customer_name, a.supplier_id, s.name as supplier_name, count(1) as total_calls, sum(case when a.match_status = 1 then a.total_tokens else 0 end) as total_tokens, sum(case when a.match_status = 1 then a.sell_amount else 0 end) as total_sell_amount, sum(case when a.match_status = 1 then a.cost_amount else 0 end) as total_cost_amount, sum(case when a.match_status = 1 then a.gross_profit else 0 end) as total_gross_profit, count(distinct case when a.match_status = 1 then a.contract_id end) as contract_count, sum(case when a.match_status <> 1 then 1 else 0 end) as abnormal_count from crm_contract_usage a left join crm_customer cu on a.customer_id = cu.id left join crm_supplier s on a.supplier_id = s.id where a.call_time >= #{startTime} and a.call_time <= #{endTime}
and a.supplier_id in
#{supplierId}
group by a.customer_id, cu.name, a.supplier_id, s.name order by total_sell_amount desc, total_cost_amount desc, a.customer_id, a.supplier_id

select a.supplier_id, s.name as supplier_name, count(1) as total_calls, sum(a.total_tokens) as total_tokens, sum(a.sell_amount) as total_sell_amount, sum(a.cost_amount) as total_cost_amount, sum(a.gross_profit) as total_gross_profit from crm_contract_usage a left join crm_supplier s on a.supplier_id = s.id where a.match_status = 1 and a.call_time >= #{startTime} and a.call_time <= #{endTime}
and a.supplier_id in
#{supplierId}
group by a.supplier_id, s.name having sum(a.cost_amount) > 0 order by total_cost_amount desc limit #{limit}

select count(1) as total_calls, ifnull(sum(case when match_status = 1 then total_tokens else 0 end), 0) as total_tokens, ifnull(sum(case when match_status = 1 then sell_amount else 0 end), 0) as total_sell_amount, ifnull(sum(case when match_status = 1 then cost_amount else 0 end), 0) as total_cost_amount, ifnull(sum(case when match_status = 1 then gross_profit else 0 end), 0) as total_gross_profit, ifnull(sum(case when match_status <> 1 then 1 else 0 end), 0) as abnormal_count from crm_contract_usage where call_time >= #{startTime} and call_time <= #{endTime}
and supplier_id in
#{supplierId}

select date_format(call_time, '%Y-%m') as bill_cycle, count(1) as total_calls, ifnull(sum(case when match_status = 1 then total_tokens else 0 end), 0) as total_tokens, ifnull(sum(case when match_status = 1 then sell_amount else 0 end), 0) as total_sell_amount, ifnull(sum(case when match_status = 1 then cost_amount else 0 end), 0) as total_cost_amount, ifnull(sum(case when match_status = 1 then gross_profit else 0 end), 0) as total_gross_profit, ifnull(sum(case when match_status <> 1 then 1 else 0 end), 0) as abnormal_count from crm_contract_usage where call_time >= #{startTime} and call_time <= #{endTime}
and supplier_id in
#{supplierId}
group by date_format(call_time, '%Y-%m') order by bill_cycle asc
